<script setup lang="ts">
import { useWorkspaceLabels } from '@/lib/workspaceLabels'
const label=useWorkspaceLabels()
import { computed, onMounted, ref, watch, nextTick } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { invoke } from '@tauri-apps/api/core'
import { executeQuery } from '@/lib/database'
import { useI18n } from '@/lib/i18n'
import { useDialogKeyboard } from '@/composables/useDialogKeyboard'
import { useToast } from '@/composables/useToast'
const route=useRoute(),router=useRouter(),toast=useToast(),{formatCurrency,pick}=useI18n()
const kind=computed(()=>route.path==='/estimates'?'estimate':'preorder'), title=computed(()=>kind.value==='estimate'?label('Estimates'):label('Customer Pre-orders'))
type Doc={id:string;number:string;kind:string;customer_id:string|null;customer_name:string;document_date:string;due_date:string|null;notes:string;status:string;subtotal_cents:number;invoice_id:string|null;invoice_number?:string}
type Product={id:string;name:string;sku:string;unit_price:number;pack_size:number;sell_by_loose_unit:boolean}
type Line={productId:string;quantity:number;price:number}
type Customer={id:string;name:string}
const documents=ref<Doc[]>([]),products=ref<Product[]>([]),customers=ref<Customer[]>([]),loading=ref(false),busy=ref(false),error=ref(''),editing=ref(false),query=ref(''),filter=ref('all'),productQuery=ref(''),productId=ref(''),printing=ref<Doc|null>(null),printLines=ref<Array<{name:string;quantity:number;unit_price_cents:number}>>([])
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const blank=()=>({id:null as string|null,customerId:'',customerName:'',documentDate:today(),dueDate:'',notes:'',items:[] as Line[]})
const form=ref(blank())
const editorDialog=ref<HTMLElement|null>(null)
useDialogKeyboard(editorDialog,()=>{if(!busy.value)editing.value=false})
const expired=(d:Doc)=>d.kind==='estimate'&&!!d.due_date&&d.due_date<today()
const total=computed(()=>form.value.items.reduce((sum,l)=>sum+Math.round(Number(l.price)*100)*Number(l.quantity),0)/100)
const visible=computed(()=>documents.value.filter(d=>(filter.value==='all'||d.status===filter.value)&&`${d.number} ${d.customer_name} ${d.notes}`.toLowerCase().includes(query.value.toLowerCase())))
const matches=computed(()=>products.value.filter(p=>`${p.name} ${p.sku}`.toLowerCase().includes(productQuery.value.toLowerCase())))
onMounted(load);watch(()=>route.path,()=>{editing.value=false;filter.value='all';query.value='';void load()})
async function load(){loading.value=true;error.value='';try{
 const [docs,ps,cs]=await Promise.all([
 executeQuery<Doc>("SELECT d.*,i.invoice_number FROM commercial_documents d LEFT JOIN sales_dashboard i ON i.id=d.invoice_id WHERE d.kind=? ORDER BY d.created_at DESC",[kind.value]),
 executeQuery<Product>("SELECT id,name,sku,unit_price,pack_size,sell_by_loose_unit FROM products WHERE deleted_at IS NULL AND is_active=1 ORDER BY name"),
 executeQuery<Customer>("SELECT id,first_name || ' ' || last_name || ' · ' || customer_code AS name FROM customers WHERE deleted_at IS NULL AND is_active=1 ORDER BY first_name")]);documents.value=docs;products.value=ps;customers.value=cs
}catch(e){error.value=String(e)}finally{loading.value=false}}
function create(){form.value=blank();productId.value='';productQuery.value='';editing.value=true}
function chooseCustomer(){const c=customers.value.find(c=>c.id===form.value.customerId);if(c)form.value.customerName=c.name}
function add(){const p=products.value.find(p=>p.id===productId.value);if(!p)return;if(form.value.items.some(l=>l.productId===p.id)){toast.warning('This item is already on the document');return}form.value.items.push({productId:p.id,quantity:p.sell_by_loose_unit?1:p.pack_size,price:p.unit_price});productId.value=''}
async function edit(d:Doc){try{const items=await executeQuery<{product_id:string;quantity:number;unit_price_cents:number}>("SELECT product_id,quantity,unit_price_cents FROM commercial_document_items WHERE document_id=?",[d.id]);form.value={id:d.id,customerId:d.customer_id||'',customerName:d.customer_name,documentDate:d.document_date,dueDate:d.due_date||'',notes:d.notes,items:items.map(l=>({productId:l.product_id,quantity:l.quantity,price:l.unit_price_cents/100}))};editing.value=true}catch(e){toast.error(String(e))}}
async function save(){busy.value=true;try{if(!form.value.items.length)throw new Error('Add at least one item');for(const l of form.value.items){if(!Number.isInteger(Number(l.quantity))||Number(l.quantity)<1||!Number.isFinite(Number(l.price))||Number(l.price)<0||Math.abs(Number(l.price)*100-Math.round(Number(l.price)*100))>0.00001)throw new Error('Use whole unit quantities and prices with at most two decimals')}
 await invoke('save_commercial_document',{request:{...form.value,kind:kind.value,customerId:form.value.customerId||null,dueDate:form.value.dueDate||null,items:form.value.items.map(l=>({productId:l.productId,quantity:Number(l.quantity),unitPriceCents:Math.round(Number(l.price)*100)}))}});editing.value=false;toast.success('Document saved');await load()
}catch(e){toast.error(String(e))}finally{busy.value=false}}
async function cancel(d:Doc){if(!confirm(`Cancel ${d.number}?`))return;busy.value=true;try{await invoke('cancel_commercial_document',{id:d.id});await load()}catch(e){toast.error(String(e))}finally{busy.value=false}}
async function print(d:Doc){try{printLines.value=await executeQuery("SELECT p.name,l.quantity,l.unit_price_cents FROM commercial_document_items l JOIN products p ON p.id=l.product_id WHERE l.document_id=?",[d.id]);printing.value=d;await nextTick();document.body.classList.add('printing-commercial');const clean=()=>{document.body.classList.remove('printing-commercial');printing.value=null};window.addEventListener('afterprint',clean,{once:true});try{window.print()}catch{clean()}}catch(e){toast.error(String(e))}}
function checkout(d:Doc){void router.push({path:'/pos',query:{document:d.id}})}
</script>
<template>
 <div class="tool-terminal documents-terminal">
  <header class="tool-header"><div><h1>{{ title }}</h1><p>{{ kind==='estimate'?'Prepare and print quotations, then convert to a sale':'Track requested products and fulfil through Sales' }}</p></div><button @click="create">+ {{ kind==='estimate'?label('New estimate'):label('New pre-order') }}</button></header>
  <div class="commercial-filters"><input v-model="query" type="search" :placeholder="label('Search number or customer')" aria-label="Search documents"/><select v-model="filter" aria-label="Document status"><option value="all">{{ label('All statuses') }}</option><option value="open">{{ label('Open') }}</option><option value="converted">{{ label('Converted to sale') }}</option><option value="cancelled">{{ label('Cancelled') }}</option></select><button :disabled="loading" @click="load">{{ label('Refresh') }}</button></div>
  <p class="commercial-hint">Quantities and prices are per base unit. {{ kind==='estimate'?'Quoted totals exclude checkout tax and discounts.':'Pre-orders do not reserve stock or collect deposits.' }} Conversion uses current prices, tax and available unexpired stock; review the sale before checkout.</p>
  <p v-if="error" class="commercial-error" role="alert">{{ error }}</p>
  <div class="commercial-table-scroll"><p v-if="loading" role="status">Loading documents…</p><table v-else><thead><tr><th>{{ label('Number / date') }}</th><th>{{ label('Customer') }}</th><th>{{ kind==='estimate'?label('Valid until'):label('Expected date') }}</th><th>{{ label('Quoted subtotal') }}</th><th>{{ label('Status / invoice') }}</th><th>{{ label('Actions') }}</th></tr></thead><tbody><tr v-for="d in visible" :key="d.id"><td>{{ d.number }}<small>{{ d.document_date }}</small></td><td>{{ d.customer_name }}</td><td>{{ d.due_date||'—' }}<small v-if="expired(d)" class="commercial-error">{{ pick('Expired — edit validity date', 'میعاد ختم — تاریخ درست کریں') }}</small></td><td>{{ formatCurrency(d.subtotal_cents/100) }}</td><td>{{ d.status }}<small>{{ d.invoice_number }}</small></td><td><button @click="print(d)">{{ label('Print / view') }}</button> <template v-if="d.status==='open'"><button @click="edit(d)">{{ label('Edit') }}</button> <button class="bg-primary" :disabled="expired(d)" :title="expired(d)?'Renew the validity date before loading this estimate':'Load into Sales'" @click="checkout(d)">{{ label('Load into Sales') }}</button> <button :disabled="busy" @click="cancel(d)">{{ label('Cancel') }}</button></template></td></tr><tr v-if="!visible.length"><td colspan="6" class="commercial-empty">{{ label('No documents match these filters.') }}</td></tr></tbody></table></div>
  <footer class="tool-summary"><div><small>{{ label('Documents shown') }}</small><strong>{{ visible.length }}</strong></div><div><small>{{ label('Open quoted value') }}</small><strong>{{ formatCurrency(visible.filter(d=>d.status==='open').reduce((s,d)=>s+d.subtotal_cents,0)/100) }}</strong></div></footer>
  <div v-if="editing" class="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4"><form ref="editorDialog" tabindex="-1" class="commercial-dialog commercial-document-editor" role="dialog" aria-modal="true" :aria-label="title" @submit.prevent="save"><header class="tool-header"><h2>{{ form.id ? (kind==='estimate'?pick('Edit estimate','تخمینے میں ترمیم'):pick('Edit pre-order','پیشگی آرڈر میں ترمیم')) : (kind==='estimate'?label('New estimate'):label('New pre-order')) }}</h2><button type="button" :disabled="busy" @click="editing=false">{{ label('Close') }}</button></header>
   <p v-if="kind==='preorder'" class="commercial-hint">{{ pick('Pre-orders do not reserve stock or collect deposits. Availability is checked when loading into Sales and again at checkout.', 'پیشگی آرڈر اسٹاک محفوظ نہیں کرتے اور پیشگی رقم وصول نہیں کرتے۔ فروخت میں لوڈ کرتے اور مکمل کرتے وقت اسٹاک کی جانچ ہوتی ہے۔') }}</p>
   <div class="commercial-form-grid"><label>{{ label('Registered customer') }}<select v-model="form.customerId" :required="kind==='preorder'" @change="chooseCustomer"><option value="">{{ label('Guest / enter name') }}</option><option v-for="c in customers" :value="c.id" :key="c.id">{{ c.name }}</option></select></label><label>{{ label('Customer name') }}<input v-model="form.customerName" required maxlength="150"/></label><label>{{ label('Date') }}<input v-model="form.documentDate" type="date" required/></label><label>{{ kind==='estimate'?label('Valid until (optional)'):label('Expected date (optional)') }}<input v-model="form.dueDate" type="date" :min="form.documentDate"/></label></div>
   <div class="commercial-filters"><input v-model="productQuery" :placeholder="label('Filter products by name or SKU')" aria-label="Filter products"/><select v-model="productId" :aria-label="label('Choose product')"><option value="">{{ label('Choose product') }}</option><option v-for="p in matches" :value="p.id" :key="p.id">{{ p.name }} · {{ p.sku }}</option></select><button type="button" @click="add">{{ label('Add item') }}</button></div>
   <div class="commercial-editor-lines"><table><thead><tr><th>{{ label('Product') }}</th><th>{{ label('Units') }}</th><th>{{ label('Price / unit (Rs)') }}</th><th>{{ label('Amount') }}</th><th></th></tr></thead><tbody><tr v-for="(l,index) in form.items" :key="l.productId"><td>{{ products.find(p=>p.id===l.productId)?.name||'Unavailable product' }}<small>Pack: {{ products.find(p=>p.id===l.productId)?.pack_size }} units</small></td><td><input v-model.number="l.quantity" type="number" min="1" step="1" required aria-label="Unit quantity"/></td><td><input v-model.number="l.price" type="number" min="0" step="0.01" required aria-label="Quoted unit price"/></td><td>{{ formatCurrency(l.quantity*l.price) }}</td><td><button type="button" @click="form.items.splice(index,1)">{{ label('Remove') }}</button></td></tr></tbody></table></div>
   <label>{{ label('Notes') }}<textarea v-model="form.notes" maxlength="1000" rows="2"/></label><footer class="tool-summary"><strong>Subtotal {{ formatCurrency(total) }}</strong><button class="bg-primary" :disabled="busy||!form.items.length">{{ busy?label('Saving…'):label('Save document') }}</button></footer>
  </form></div>
 </div>
 <Teleport to="body"><section v-if="printing" class="commercial-print"><h1>{{ printing.kind==='estimate'?'Estimate / Quotation':'Customer Pre-order' }}</h1><h2>{{ printing.number }}</h2><p>{{ printing.customer_name }} · {{ printing.document_date }}</p><p>{{ printing.kind==='estimate'?label('Valid until'):label('Expected date') }}: {{ printing.due_date||'Not specified' }} · {{ printing.status }}</p><table><thead><tr><th>{{ label('Product') }}</th><th>{{ label('Units') }}</th><th>Rate</th><th>{{ label('Amount') }}</th></tr></thead><tbody><tr v-for="(l,i) in printLines" :key="i"><td>{{ l.name }}</td><td>{{ l.quantity }}</td><td>{{ formatCurrency(l.unit_price_cents/100) }}</td><td>{{ formatCurrency(l.quantity*l.unit_price_cents/100) }}</td></tr></tbody></table><h2>Quoted subtotal {{ formatCurrency(printing.subtotal_cents/100) }}</h2><p>Tax and discounts are calculated at checkout. This document is not a paid sales receipt.</p><p v-if="printing.kind==='preorder'">{{ pick('No stock reservation or deposit.', 'اسٹاک محفوظ یا پیشگی رقم وصول نہیں کی گئی۔') }}</p><p>{{ printing.notes }}</p><p v-if="printing.invoice_number">Converted to {{ printing.invoice_number }}</p></section></Teleport>
</template>
